import base64
import pickle
import io


class RestrictedUnpickler(pickle.Unpickler):
    """A restricted unpickler that only allows safe built-in types."""

    SAFE_TYPES = {
        'builtins': {'dict', 'list', 'tuple', 'set', 'frozenset', 
                     'str', 'bytes', 'int', 'float', 'bool', 'NoneType'}
    }

    def find_class(self, module, name):
        # Only allow safe built-in types
        if module == 'builtins' and name in self.SAFE_TYPES['builtins']:
            return getattr(__import__(module), name)
        # For NoneType, it's accessed differently
        if module == 'builtins' and name == 'NoneType':
            return type(None)
        raise pickle.UnpicklingError(f"Global '{module}.{name}' is forbidden")


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing pickled user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Use restricted unpickler for safe deserialization
        unpickler = RestrictedUnpickler(io.BytesIO(decoded_data))
        preferences = unpickler.load()

        # Ensure the result is a dictionary
        if not isinstance(preferences, dict):
            return {}

        return preferences
    except Exception:
        # Return empty dict if any error occurs during decoding/deserialization
        return {}

